-- ============================================================================
-- Migration 758: Seed mhr_records with the 6 real Jig Bore /
-- Shaver machines, and activate their process_calculator_mappings rows
--
-- Generated by gen_757_stage_and_seed_jig_bore_shaver.js. Continues
-- migration 738's own disclosed gap (these 2 categories had zero source
-- machine data at that time) now that real data has arrived.
--
-- machine_class = snake_case(categoryLabel) -- 'jig_bore'/'shaver' -- both
-- checked directly against every MACHINE_REGISTRY key/keyword in
-- default-rates.constants.ts before use; zero collisions found (unlike
-- Drill Press/Inspection/MillTurn in migration 738, which needed a
-- rename).
--
-- roadmap_status/is_active = 'thin'/true -- same tier as the other 31
-- non-aliased real Machining categories (migration 753): real HR-rate
-- data, catalog-visible, no dedicated per-station cost engine yet. NOT
-- 'production' -- these are precision finishing operations (jig boring,
-- gear shaving), not lathe/mill work, so selector.ts's
-- MACHINING_CATEGORY_ALIAS has no coarse cnc_* bucket to alias them into.
-- ============================================================================

BEGIN;

INSERT INTO mhr_records (
  machine_class, location, machine_name, currency_code, country_code, source_type, process_family, process_group, operators, setup_time_hr, press_cycle_time_s, direct_overhead_rate, indirect_overhead_rate, benchmark_direct_overhead_rate_usd_hr, benchmark_indirect_overhead_rate_usd_hr, total_machine_hour_rate, mhr_usd_per_hour, usd_labor_rate_per_hr, benchmark_labor_rate_usd_hr, usd_lhr_total, work_center_labor_rate_factor, labor_time_standard, wage_grade, machine_price_usd, machine_length_mm, machine_width_mm, footprint_allowance_factor, machine_power_kw, machine_life_yr, installation_factor_pct, machine_uptime_pct, annual_maintenance_factor_pct, salvage_value_factor_pct, supplies_cost_per_year, avg_utilization, good_part_yield, manufacturer_country, benchmark_source_key
) VALUES
  ($str$jig_bore$str$, $str$USA$str$, $str$SIP Hydroptic 6A$str$, $str$USD$str$, $str$US$str$, $str$BENCHMARK$str$, $str$machined$str$, $str$Machining$str$, 1, 1, NULL, 9.25, 14.49, 9.25, 14.49, 23.74, 23.74, 29.95, 29.95, 29.95, 1, 1, $str$2 - Metal$str$, 138000, 3280, 2335, 1, 5.96, 10, 20, 80, 5, 0, 0, 1, 1, $str$Switzerland$str$, $str$Jig Bore:SIP Hydroptic 6A$str$),
  ($str$jig_bore$str$, $str$USA$str$, $str$Virtual CNC Jig Bore$str$, $str$USD$str$, $str$US$str$, $str$BENCHMARK$str$, $str$machined$str$, $str$Machining$str$, 1, 1, NULL, 24.12, 14.49, 24.12, 14.49, 38.61, 38.61, 29.95, 29.95, 29.95, 1, 1, $str$2 - Metal$str$, 250000, 3280, 2335, 1, 59.5, 10, 20, 80, 5, 0, 0, 1, 1, $str$Virtual$str$, $str$Jig Bore:Virtual CNC Jig Bore$str$),
  ($str$jig_bore$str$, $str$USA$str$, $str$Virtual Manual Jig Bore$str$, $str$USD$str$, $str$US$str$, $str$BENCHMARK$str$, $str$machined$str$, $str$Machining$str$, 1, 1, NULL, 9.25, 14.49, 9.25, 14.49, 23.74, 23.74, 29.95, 29.95, 29.95, 1, 1, $str$2 - Metal$str$, 138000, 3280, 2335, 1, 5.96, 10, 20, 80, 5, 0, 0, 1, 1, $str$Virtual$str$, $str$Jig Bore:Virtual Manual Jig Bore$str$),
  ($str$jig_bore$str$, $str$USA$str$, $str$YASDA YBM1218V Jig Bore$str$, $str$USD$str$, $str$US$str$, $str$BENCHMARK$str$, $str$machined$str$, $str$Machining$str$, 1, 1, NULL, 24.12, 14.49, 24.12, 14.49, 38.61, 38.61, 29.95, 29.95, 29.95, 1, 1, $str$2 - Metal$str$, 250000, 3280, 2335, 1, 59.5, 10, 20, 80, 5, 0, 0, 1, 1, $str$Japan$str$, $str$Jig Bore:YASDA YBM1218V Jig Bore$str$),
  ($str$shaver$str$, $str$USA$str$, $str$Gleason Genesis 130 SV$str$, $str$USD$str$, $str$US$str$, $str$BENCHMARK$str$, $str$machined$str$, $str$Machining$str$, 1, 3, NULL, 42.41, 15.5, 42.41, 15.5, 57.91, 57.91, 36.3, 36.3, 36.3, 1, 1, $str$3 - Metal$str$, 637000, 2600, 2500, 3, 25.5, 10, 20, 80, 5, 0, 0, 0.5, 1, $str$USA$str$, $str$Shaver:Gleason Genesis 130 SV$str$),
  ($str$shaver$str$, $str$USA$str$, $str$Gleason ZS300 Gear Shaver$str$, $str$USD$str$, $str$US$str$, $str$BENCHMARK$str$, $str$machined$str$, $str$Machining$str$, 1, 3, NULL, 46.61, 15.91, 46.61, 15.91, 62.52, 62.52, 36.3, 36.3, 36.3, 1, 1, $str$3 - Metal$str$, 730000, 3370, 2400, 3, 16, 10, 20, 80, 5, 0, 0, 0.5, 1, $str$USA$str$, $str$Shaver:Gleason ZS300 Gear Shaver$str$)
;

UPDATE process_taxonomy
SET machine_class = 'jig_bore', roadmap_status = 'thin'
WHERE process_group = 'Machining' AND process_name = 'Jig Bore';

UPDATE process_taxonomy
SET machine_class = 'shaver', roadmap_status = 'thin'
WHERE process_group = 'Machining' AND process_name = 'Shaver';

UPDATE process_calculator_mappings
SET machine_class = 'jig_bore', is_active = true, updated_at = NOW()
WHERE process_group = 'Machining' AND process_route = 'Jig Bore';

UPDATE process_calculator_mappings
SET machine_class = 'shaver', is_active = true, updated_at = NOW()
WHERE process_group = 'Machining' AND process_route = 'Shaver';

COMMIT;

